<template>
	<view class="growth-page" :class="[{'motion-reduced':reducedMotion}, zyThemeClass]">
 <view class="growth-hero journey-hero"><view><text class="growth-eyebrow">GROWTH JOURNEY · 成长旅程</text><text class="growth-title">每一小步，都算数</text><text class="growth-subtitle">记录是为了认识自己，无需和任何人比较。</text></view></view>
 <view v-if="error" class="growth-error">{{error}}<AccessibleButton class="growth-button secondary" @click="load">重新加载</AccessibleButton></view><text v-if="loading" class="growth-muted">正在整理你的旅程…</text>
 <view class="growth-card practice-recent"><view class="growth-row growth-spread"><view><text class="growth-card-title">最近的练习</text><text class="growth-muted">一次一件，按自己的节奏。</text></view><AccessibleButton class="growth-button secondary practice-new" @click="goStart">开始新的</AccessibleButton></view><text v-if="practiceLoading" class="growth-muted">正在读取练习记录…</text><view v-else-if="practiceError" class="growth-error">{{practiceError}}<AccessibleButton class="growth-button secondary" @click="loadPractices">重试</AccessibleButton></view><text v-else-if="!practiceSessions.length" class="growth-muted">还没有练习记录，可以从「此刻」开始一段 15 分钟的非遗手作。</text><view v-for="item in practiceSessions" :key="item.practiceSessionId" class="practice-row"><view class="practice-row-copy"><text class="practice-row-title">{{practiceKindLabel(item.kind)}} · {{item.minutesBudget}} 分钟</text><text class="growth-muted">{{item.statusLabel}} · {{formatPracticeTime(item.createTime)}}</text></view><AccessibleButton class="growth-button secondary" @click="openPractice(item)">{{isActivePractice(item)?'继续':'回看'}}</AccessibleButton></view></view>
 <template v-if="data">
 <view class="growth-card growth-row growth-spread"><view v-for="s in stats" :key="s.label"><text class="metric">{{s.value}}</text><text class="growth-muted">{{s.label}}</text></view></view>
 <view class="growth-card"><text class="growth-card-title">今天，感觉如何？</text><view class="growth-row moods"><AccessibleButton v-for="(m,i) in moods" :aria-pressed="mood===i+1" :key="m" :class="['growth-choice',{selected:mood===i+1}]" @click="mood=i+1">{{m}}</AccessibleButton></view><textarea class="growth-input growth-textarea" v-model="note" aria-label="今日感受备注，选填" maxlength="500" placeholder="想留下一句话吗？（选填）"/><checkbox-group @change="consent=$event.detail.value.length>0"><label class="growth-consent"><checkbox value="yes" :checked="consent" color="#217e76"/>同意将本次感受加密保存到我的成长记录，可随时清除。</label></checkbox-group><AccessibleButton class="growth-button" :disabled="busy||!consent||!mood" @click="save">{{busy?'正在保存…':'保存今日感受'}}</AccessibleButton></view>
 <view class="growth-card"><view class="growth-row growth-spread"><text class="growth-card-title">{{monthLabel}}</text><view class="growth-row"><AccessibleButton class="calendar-nav" @click="changeMonth(-1)">上月</AccessibleButton><AccessibleButton class="calendar-nav" @click="changeMonth(1)">下月</AccessibleButton></view></view><view class="calendar"><text v-for="w in ['一','二','三','四','五','六','日']" :key="w" class="week">{{w}}</text><AccessibleButton v-for="(d,i) in calendar" :disabled="!d" :aria-label="d ? d+(dayRecords[d]?' 有感受记录':' 未记录') : '空白日期'" :key="i" :class="['day',{recorded:d&&dayRecords[d],selected:d&&selectedDay===d}]" @click="selectedDay=d"><text>{{d?Number(d.slice(-2)):''}}</text><text v-if="d&&dayRecords[d]" class="dot">●</text></AccessibleButton></view><text class="growth-muted">{{selectedDay && dayRecords[selectedDay] ? selectedDay+' · '+moods[dayRecords[selectedDay].mood-1]+'\n'+(dayRecords[selectedDay].note||'') : '点选已标记的日期，回看当天的感受。'}}</text></view>
 <view class="growth-card"><text class="growth-card-title">近两周的感受</text><text class="growth-muted">只呈现你记录的感受，空白日不作推断。</text><view class="mood-trend"><AccessibleButton v-for="d in trendDays" :key="d.key" class="trend-column" :aria-label="d.key+(d.record?' '+moods[d.record.mood-1]:' 未记录')" @click="selectedDay=d.key;month=new Date(d.key.slice(0,7)+'-01T12:00:00')"><view class="trend-track"><view v-if="d.record" class="trend-bar" :style="{height:d.record.mood*20+'%'}"/><text v-else class="trend-empty">—</text></view><text>{{d.day}}</text></AccessibleButton></view><text class="growth-muted">这是主观感受回看，不用于判断干预效果。</text></view><view class="growth-card"><text class="growth-card-title">我的里程碑</text><view class="growth-row"><text v-for="b in data.badges" :key="b" class="growth-tag">{{b}}</text><text v-if="!data.badges.length" class="growth-muted">完成一次创作，点亮第一枚纪念徽章。</text></view><text class="growth-muted">连续记录 {{data.streak}} 天 · 不必为了连续天数勉强自己。</text></view>
 <JourneyInsights :records="data.records" :limit="data.limit" :truncated="data.truncated"/><view class="growth-card"><text class="growth-card-title">最近记录</text><text v-if="!history.length" class="growth-muted">还没有记录，从今天开始也很好。</text><view v-for="r in history.slice(0,historyLimit)" :key="r.id" class="history"><text>{{r.kind==='REFLECTION'?(r.title||'创作感受'):r.kind==='LISTENING_SUMMARY'?'倾听小结':r.scale+' · '+(r.kind==='DRAFT'?'未完成':r.score+' 分')}}</text><text class="growth-muted">{{r.date.slice(0,16)}}{{r.kind==='REFLECTION'?' · '+moods[r.afterMood-1]:(r.kind==='LISTENING_SUMMARY'?' · 已保存':'')}}</text><text v-if="r.kind==='ASSESSMENT'" class="growth-muted">{{r.message}} 结果不构成诊断。</text><text v-if="r.kind==='LISTENING_SUMMARY'" class="growth-muted">{{summaryDisplay(r)}}</text><text v-if="r.note" class="growth-muted">{{r.note}}</text><AccessibleButton v-if="r.kind==='DRAFT'" class="growth-button secondary" @click="resume(r.scale)">继续作答</AccessibleButton><AccessibleButton v-if="r.kind==='LISTENING_SUMMARY'" class="growth-button secondary" @click="removeListening(r)">删除这条小结</AccessibleButton></view><AccessibleButton v-if="history.length>historyLimit" class="growth-button secondary" @click="historyLimit+=20">查看更多记录</AccessibleButton><text class="growth-muted">已载入 {{data.records.length}} 条记录{{data.truncated?'，较早记录未载入':''}}。</text></view>
 <AccessibleButton class="growth-button danger" :disabled="busy" @click="erase">清除我的感受与自评记录</AccessibleButton>
 </template><text class="growth-foot">本系统不能替代专业心理咨询</text><ActionSheet :open="!!pendingRemoveListening" title="删除倾听小结" description="只删除这条小结，不删除倾听对话。是否继续？" :actions="[{key:'confirm',label:'确认删除',tone:'danger'}]" cancel-text="再想想" @select="confirmRemoveListening" @close="pendingRemoveListening=null"/><ActionSheet :open="pendingErase" title="清除个人记录" description="永久清除心情、自评、创作感受与活动反馈。作品、创作会话和报名不受影响。此操作不能撤销。" :actions="[{key:'confirm',label:'确认清除',tone:'danger',busy:busy}]" cancel-text="再想想" :busy="busy" @select="confirmErase" @close="pendingErase=false"/><Toast/>
</view></template>
<script setup>
import JourneyInsights from '../../components/JourneyInsights.vue'
import ActionSheet from '../../components/ActionSheet.vue'
import Toast from '../../components/Toast.vue'
import AccessibleButton from '../../components/AccessibleButton.vue'
import {useInteraction} from '../../composables/useInteraction'
import {useToast} from '../../composables/useToast'
const {reducedMotion}=useInteraction()
const toast=useToast()

import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import {request} from '../../utils/request';import {summaryDisplay} from '../../utils/listening-summary';import {listPracticeSessions,isActivePractice,practiceKindLabel} from '../../utils/practice-session'
const historyLimit=ref(20),practiceSessions=ref([]),practiceLoading=ref(false),practiceError=ref('')
const data=ref(null),loading=ref(false),busy=ref(false),error=ref(''),mood=ref(0),note=ref(''),consent=ref(false),selectedDay=ref(''),month=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1));const moods=['很低落','有些低落','平静','还不错','很开心']
const stats=computed(()=>[{label:'创作天数',value:data.value.days},{label:'完成创作',value:data.value.completed},{label:'专注分钟',value:Number.isFinite(data.value.flowSeconds)?Math.floor(data.value.flowSeconds/60):'—'}]);const dayRecords=computed(()=>Object.fromEntries((data.value?.records||[]).filter(r=>r.kind==='MOOD').map(r=>[r.key,r])));const history=computed(()=>(data.value?.records||[]).filter(r=>['REFLECTION','ASSESSMENT','DRAFT','LISTENING_SUMMARY'].includes(r.kind)))
const trendDays=computed(()=>Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return{key,day:d.getDate(),record:dayRecords.value[key]}}))
const monthLabel=computed(()=>month.value.getFullYear()+' 年 '+(month.value.getMonth()+1)+' 月');const calendar=computed(()=>{const y=month.value.getFullYear(),m=month.value.getMonth();return [...Array((month.value.getDay()+6)%7).fill(''),...Array.from({length:new Date(y,m+1,0).getDate()},(_,i)=>y+'-'+String(m+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0'))]});function changeMonth(n){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+n,1)}
async function load(){loading.value=true;error.value='';try{data.value=await request({url:'/api/growth/journey'});const today=new Date().toLocaleDateString('sv-SE');const record=dayRecords.value[today];if(record){mood.value=record.mood;note.value=record.note||''}}catch(e){error.value=e.message||'加载失败'}finally{loading.value=false}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await request({url:'/api/growth/mood',method:'PUT',data:{mood:mood.value,note:note.value,consent:consent.value}});toast.success('已保存');await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function resume(scale){uni.navigateTo({url:'/pages/assessment/index?scale='+scale})}
const pendingRemoveListening=ref(null),pendingErase=ref(false)
function removeListening(r){pendingRemoveListening.value=r}
async function confirmRemoveListening(){const r=pendingRemoveListening.value;if(!r)return;pendingRemoveListening.value=null;try{await request({url:'/api/emotion/sessions/'+r.sessionId+'/summary',method:'DELETE'});await load()}catch(e){error.value=e.message}}
function erase(){if(busy.value)return;pendingErase.value=true}
async function confirmErase(){if(busy.value)return;pendingErase.value=false;busy.value=true;try{await request({url:'/api/growth/records',method:'DELETE'});mood.value=0;note.value='';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadPractices(){practiceLoading.value=true;practiceError.value='';try{practiceSessions.value=(await listPracticeSessions(5))||[]}catch(e){practiceError.value=(e&&e.message)||'练习记录暂时没有载入'}finally{practiceLoading.value=false}}
function formatPracticeTime(value){return value?String(value).slice(0,16).replace('T',' '):''}
function goStart(){uni.navigateTo({url:'/pages/start/index'})}
function openPractice(item){const patternId=item&&item.heritagePatternId?String(item.heritagePatternId):'';const status=Number(item&&item.status);if(patternId&&(isActivePractice(item)||status===5||status===6)){uni.navigateTo({url:'/sub-heritage/pages/heritage/studio?id='+encodeURIComponent(patternId)+'&sessionId='+encodeURIComponent(item.practiceSessionId)});return}if(patternId){uni.navigateTo({url:'/sub-heritage/pages/heritage/detail?id='+encodeURIComponent(patternId)});return}uni.navigateTo({url:isActivePractice(item)?'/sub-heritage/pages/heritage/gallery':'/pages/start/index'})}
onShow(()=>{load();loadPractices()})
</script><style scoped>.calendar-nav{font-size:var(--zy-text-caption, 24rpx);line-height:2;background:transparent;color:var(--zy-brand-700, #1a645e);padding:0;margin:0}.calendar-nav::after{border:0}.day.selected{outline:2rpx solid var(--zy-brand-700, #1a645e)}.mood-trend{display:flex;gap:5rpx;margin:24rpx 0}.trend-column{flex:1;min-width:0;margin:0;padding:0;background:transparent;color:#688075;font-size:var(--zy-text-micro, 22rpx);line-height:2;flex-direction:column;align-items:center}.trend-column::after{border:0}.trend-track{height:130rpx;display:flex;align-items:flex-end;justify-content:center;align-self:stretch}.trend-bar{width:60%;background:#75baa2;border-radius:6rpx 6rpx 0 0;min-height:8rpx;transition:height .2s ease}.trend-empty{align-self:center;color:#a0b3a8}.moods .growth-choice{width:auto;line-height:1.6;margin:12rpx 0;min-height:76rpx}.metric{display:block;font-size:var(--zy-text-title-lg, 40rpx);font-weight:650}.calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:8rpx;margin:20rpx 0}.week{text-align:center;color:#708585;font-size:var(--zy-text-caption, 24rpx)}.day{height:68rpx;display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:12rpx;font-size:var(--zy-text-caption, 24rpx)}.recorded{background:#e7f4ed;color:var(--zy-brand-700, #1a645e)}.dot{font-size:var(--zy-text-micro, 22rpx)}.history{padding:24rpx 0;border-bottom:1rpx solid var(--zy-border,#e2e9e9);display:flex;flex-direction:column;gap:10rpx}.moods{gap:8rpx}.moods .growth-choice{padding:14rpx 10rpx;font-size:var(--zy-text-caption, 24rpx);flex:1;text-align:center}</style>

<style scoped>.growth-page{max-width:1180px;margin:auto}.journey-hero{display:flex;align-items:center;justify-content:space-between;gap:20rpx}.journey-pet{flex-shrink:0}.calendar .day{padding:0;margin:0;width:100%;min-height:44px;line-height:1.3;background:transparent;color:#233d34}.calendar .day.recorded{background:#e7f4ed}.calendar .day::after{border:0}.calendar .day.is-disabled{opacity:0}.calendar-nav{min-height:44px;min-width:44px}.history{overflow-wrap:anywhere}.growth-page .metric{font-variant-numeric:tabular-nums}.practice-recent{margin-bottom:24rpx}.practice-new{flex:0 0 auto;min-height:44px}.practice-row{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12rpx;padding:18rpx 0;border-bottom:1rpx solid var(--zy-border,#e2e9e9)}.practice-row:last-child{border-bottom:0}.practice-row-copy{flex:1 1 320rpx;min-width:0}.practice-row-title{display:block;font-size:var(--zy-text-caption, 24rpx);color:var(--zy-title,#233d34)}.practice-row .growth-muted{display:block;margin-top:4rpx;font-size:var(--zy-text-micro, 22rpx)}.practice-row .growth-button{flex:0 0 auto;min-height:44px}.practice-row .growth-button{border:0;background:transparent;color:var(--zy-brand-700,#0a403b);font-size:var(--zy-text-caption,24rpx);line-height:1.8;padding:0;margin:0;width:auto;min-height:0;flex-shrink:0}.practice-row .growth-button::after{border:0}.practice-row-title{font-family:var(--zy-font-display,'Songti SC',serif);font-size:30rpx;font-weight:500;color:var(--zy-title,#111816)}
</style>
